import type { GalleryOptions as LegacyGalleryOptions } from './../../../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { GalleryOptions } from './../../../../ricos-schema/next-schema/index.js';

import { resolveGalleryLayout } from '../../../viewer/resolve-gallery-layout.js';

export const canonicalizeLegacyCollageOptions = (options: GalleryOptions): GalleryOptions => {
  if (options.layout?.type !== 'COLLAGE') {
    return options;
  }

  const layout = resolveGalleryLayout({
    options: options as unknown as LegacyGalleryOptions,
    isMobile: false,
  });
  if (layout.type !== 'MASONRY') {
    return options;
  }

  return {
    layout: {
      type: 'MASONRY',
      orientation: layout.orientation,
      // Horizontal Masonry is compatibility-only and has no editor control,
      // so the first live edit must return the gallery to an editable flow.
      horizontalScroll: false,
    },
    item: {
      targetSize: layout.targetSize,
      spacing: layout.spacing,
    },
  };
};
