import classNames from 'classnames';
import React, { useCallback, useEffect, useRef, useState } from 'react';

import { GalleryThumbnailMedia } from '../media/gallery-media.js';
import { getHorizontalGalleryScrollBehavior } from '../media/horizontal-gallery-scroll.js';
import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import { LayoutFullsize, type LayoutFullsizeHandle } from './layout-fullsize.js';
import classes from './layout-thumbnail-scss.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';
import type { ResolvedGalleryLayout } from './resolve-gallery-layout.js';

type LayoutThumbnailResolved = Extract<ResolvedGalleryLayout, { type: 'THUMBNAIL' }>;

type LayoutThumbnailProps = {
  items: NormalizedGalleryItem[];
  layout: LayoutThumbnailResolved;
  nodeId: string;
  runtime: GalleryRendererRuntime;
};

export const LayoutThumbnail = ({ items, layout, nodeId, runtime }: LayoutThumbnailProps) => {
  const fullsizeRef = useRef<LayoutFullsizeHandle>(null);
  const thumbnailRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const previousActiveIndex = useRef(0);
  const [activeIndex, setActiveIndex] = useState(0);

  const handleActiveIndexChange = useCallback((index: number) => {
    setActiveIndex(index);
  }, []);

  useEffect(() => {
    if (activeIndex === previousActiveIndex.current) {
      return;
    }
    previousActiveIndex.current = activeIndex;
    thumbnailRefs.current[activeIndex]?.scrollIntoView?.({
      behavior: getHorizontalGalleryScrollBehavior(),
      block: 'nearest',
      inline: 'nearest',
    });
  }, [activeIndex]);

  const thumbnailStyle = {
    '--ricos-internal-gallery-thumbnail-spacing': `${layout.spacing}px`,
  } as React.CSSProperties;
  const placementClass = classes[`placement${layout.placement}`];

  return (
    <div className={classes.thumbnailContainer}>
      <div
        className={classNames(classes.thumbnail, placementClass)}
        style={thumbnailStyle}
        data-hook="gallery-thumbnail"
        data-placement={layout.placement}
      >
        <LayoutFullsize
          ref={fullsizeRef}
          items={items}
          layout={{ type: 'FULLSIZE' }}
          nodeId={nodeId}
          runtime={runtime}
          onActiveIndexChange={handleActiveIndexChange}
        />
        {layout.placement !== 'NONE' ? (
          <nav
            className={classes.thumbnailNavigation}
            aria-label={runtime.thumbnailNavigationLabel}
            data-hook="gallery-thumbnail-navigation"
          >
            <ul className={classes.thumbnailList}>
              {items.map((item, index) => (
                <li key={item.id} className={classes.thumbnailItem}>
                  <button
                    ref={element => {
                      thumbnailRefs.current[index] = element;
                    }}
                    type="button"
                    className={classes.thumbnailButton}
                    aria-label={runtime.showItemLabel(index + 1, item.title)}
                    aria-current={index === activeIndex ? 'true' : undefined}
                    onClick={() => fullsizeRef.current?.activateItem(index)}
                    data-hook="gallery-thumbnail-button"
                    data-id={item.id}
                    data-source-index={item.sourceIndex}
                  >
                    <GalleryThumbnailMedia item={item} runtime={runtime} />
                  </button>
                </li>
              ))}
            </ul>
          </nav>
        ) : null}
      </div>
    </div>
  );
};
