import { TIPTAP_GALLERY_TYPE } from './../../ricos-content/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../../ricos-types/index.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { Gallery as Component } from './component.js';

const name = TIPTAP_GALLERY_TYPE;

export const tiptapExtensions = [
  createRicosNodeExtension({
    name,
    groups: ['spoilerable', 'overlay', 'draggable', 'not-overtypable'],
    type: 'react-node',
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>
    ) => ({
      ...config,
      addOptions: () => settings,
    }),
    Component,
    createExtensionConfig() {
      return {
        name: this.name,
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent listItemFirstChildContent listItemSecondChildContent',
        selectable: true,
        draggable: true,
        addAttributes: () => ({
          containerData: null,
          items: null,
          options: null,
          disableExpand: null,
          disableDownload: null,
          loading: {
            default: false,
          },
          loadingPercentage: null,
        }),
        addCommands() {
          return {};
        },
      };
    },
  }),
];
