import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import {
  Carousel,
  CarouselSmall,
  LayoutGallery,
  LayoutGallerySmall,
  LayoutSplit,
  LayoutSplitSmall,
  LayoutTwoColumnsSplit,
  LayoutTwoColumnsSplitSmall,
  MasonaryGrid,
  MasonaryGridSmall,
  Slider,
  SliderSmall,
  Thumbnails,
  ThumbnailsSmall,
} from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { GalleryOptions_Layout_Type as GALLERY_LAYOUT } from './../../ricos-schema/next-schema/index.js';
import { DropdownModal } from './../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemDivider } from './../../_shared/list-item-divider/list-item-divider.js';
import { ListItemSelect } from './../../_shared/list-item-select/list-item-select.js';
import type { SupportedLayouts } from './../common-types.js';

export const CUSTOMIZE_LAYOUT_OPTION_ID = 'customize-layout' as const;

export type LayoutDropdownProps = {
  options: (
    | {
        id: SupportedLayouts;
        text: string;
        dataHook: string;
        icon: IconComponent;
        iconMobile: IconComponent;
      }
    | {
        id: typeof CUSTOMIZE_LAYOUT_OPTION_ID;
        text: string;
        dataHook: string;
      }
  )[];
  selectedId?: SupportedLayouts;
  onSelect: (id: SupportedLayouts | typeof CUSTOMIZE_LAYOUT_OPTION_ID) => void;
  closeModal: () => void;
};

export const LayoutDropdown: React.FC<LayoutDropdownProps> = ({
  options,
  selectedId,
  onSelect,
  closeModal,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  const customizeOption = options.find(option => option.id === CUSTOMIZE_LAYOUT_OPTION_ID);

  return (
    <DropdownModal
      onCloseButtonClick={closeModal}
      title={t('GalleryPlugin_Layout_Dropdown_Title')}
      options={[
        options
          .filter(option => option.id !== CUSTOMIZE_LAYOUT_OPTION_ID)
          .map(option => (
            <ListItemSelect
              key={option.id}
              dataHook={option.dataHook}
              title={option.text}
              prefix={isMobile ? <option.iconMobile /> : <option.icon />}
              selected={option.id === selectedId}
              onSelect={() => {
                onSelect(option.id);
                closeModal();
              }}
            />
          )),
        <ListItemDivider key="divider" />,
        customizeOption && (
          <ListItemSelect
            key={customizeOption.id}
            dataHook={customizeOption.dataHook}
            title={customizeOption.text}
            onSelect={() => {
              onSelect(customizeOption.id);
              closeModal();
            }}
          />
        ),
      ]}
    />
  );
};

