import React from 'react';

import type { Transform } from './restrict-to-bounding-rect.js';
import { restrictToBoundingRect } from './restrict-to-bounding-rect.js';

// Pointer must travel this many pixels before a press becomes a drag. Below the
// threshold the gesture stays a click/double-click, so selection still works.
const ACTIVATION_DISTANCE = 5;

type Point = { x: number; y: number };

// Props spread onto each sortable item's wrapper element.
export type ItemDragProps = {
  ref: (node: HTMLElement | null) => void;
  onPointerDown: (event: React.PointerEvent) => void;
  style: React.CSSProperties;
};

type SortableGridArgs = {
  itemCount: number;
  onSortEnd: (args: { oldIndex: number; newIndex: number }) => void;
  getContainerRect: () => DOMRect | undefined;
};

export const useSortableGrid = ({ itemCount, onSortEnd, getContainerRect }: SortableGridArgs) => {
  const itemNodes = React.useRef<(HTMLElement | null)[]>([]);
  const [activeIndex, setActiveIndex] = React.useState<number | null>(null);
  const [overIndex, setOverIndex] = React.useState<number | null>(null);
  const [transform, setTransform] = React.useState<Transform | null>(null);

  // Live, non-render-critical state for the in-flight drag.
  const drag = React.useRef({
    start: { x: 0, y: 0 } as Point,
    activated: false,
    moved: false,
    index: -1,
    over: null as number | null,
    rects: [] as (DOMRect | null)[],
    cleanup: () => {},
  });

  const reset = React.useCallback(() => {
    drag.current.cleanup();
    drag.current.cleanup = () => {};
    drag.current.activated = false;
    drag.current.index = -1;
    drag.current.over = null;
    setActiveIndex(null);
    setOverIndex(null);
    setTransform(null);
  }, []);

  const onPointerDown = React.useCallback(
    (index: number) => (event: React.PointerEvent) => {
      // Only the primary button / single touch starts a drag.
      if (event.button !== 0) {
        return;
      }
      // Drop any listeners left over from a previous gesture before re-adding.
      drag.current.cleanup();
      drag.current.start = { x: event.clientX, y: event.clientY };
      drag.current.activated = false;
      drag.current.moved = false;
      drag.current.index = index;

      const handleUp = () => {
        if (drag.current.activated) {
          const oldIndex = drag.current.index;
          const newIndex = drag.current.over ?? oldIndex;
          if (oldIndex !== newIndex) {
            onSortEnd({ oldIndex, newIndex });
          }
        }
        reset();
      };

      const handleMove = (moveEvent: PointerEvent) => {
        // Liveness guard: if the button was released outside the document, the
        // document pointerup never fired — terminate instead of following a
        // button-less pointer forever.
        if (moveEvent.buttons === 0) {
          handleUp();
          return;
        }
        const pointer = { x: moveEvent.clientX, y: moveEvent.clientY };
        if (!drag.current.activated) {
          const dx = pointer.x - drag.current.start.x;
          const dy = pointer.y - drag.current.start.y;
          if (Math.hypot(dx, dy) < ACTIVATION_DISTANCE) {
            return;
          }
          // Crossed the threshold: snapshot every item's geometry once. The DOM
          // is not reordered during the drag, so these rects stay the truth.
          drag.current.activated = true;
          drag.current.moved = true;
          drag.current.rects = itemNodes.current
            .slice(0, itemCount)
            .map(itemNode => itemNode?.getBoundingClientRect() ?? null);
          setActiveIndex(index);
        }

        const containerRect = getContainerRect();
        const draggingRect = drag.current.rects[index];
        const offset: Transform = {
          x: pointer.x - drag.current.start.x,
          y: pointer.y - drag.current.start.y,
          scaleX: 1,
          scaleY: 1,
        };
        setTransform(
          containerRect && draggingRect
            ? restrictToBoundingRect(offset, draggingRect, containerRect)
            : offset
        );
        // Track the over-target in the ref synchronously (not just via state)
        // so a fast pointerup reads the final target instead of stale render
        // state and silently dropping the reorder.
        const over = getOverIndex(pointer, drag.current.rects, index);
        drag.current.over = over;
        setOverIndex(over);
      };

      // Listen on document (not the item node) and without pointer capture, so a
      // no-movement press stays a plain click: capturing would retarget the
      // click/dblclick to the wrapper and the Thumbnail's onClick would never fire.
      document.addEventListener('pointermove', handleMove);
      document.addEventListener('pointerup', handleUp);
      document.addEventListener('pointercancel', reset);
      drag.current.cleanup = () => {
        document.removeEventListener('pointermove', handleMove);
        document.removeEventListener('pointerup', handleUp);
        document.removeEventListener('pointercancel', reset);
      };
    },
    [itemCount, onSortEnd, getContainerRect, reset]
  );

  // Abort an in-flight drag if the list changes underneath it (e.g. an upload
  // completes), so we never commit a stale oldIndex/newIndex.
  React.useEffect(() => {
    if (activeIndex !== null) {
      reset();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [itemCount]);

  // Safety net: drop listeners/capture if the component unmounts mid-drag.
  React.useEffect(() => reset, [reset]);

  const getItemProps = (index: number): ItemDragProps => {
    const style: React.CSSProperties = { touchAction: 'none' };
    if (activeIndex === index && transform) {
      style.transform = `translate3d(${transform.x}px, ${transform.y}px, 0)`;
      style.transition = 'none';
      style.zIndex = 10000;
      style.cursor = 'grabbing';
    } else if (activeIndex !== null && overIndex !== null) {
      const shift = shiftFor(index, activeIndex, overIndex, drag.current.rects);
      style.transform = `translate3d(${shift.x}px, ${shift.y}px, 0)`;
      style.transition = 'transform 200ms ease';
    }
    return {
      ref: node => {
        itemNodes.current[index] = node;
      },
      onPointerDown: onPointerDown(index),
      style,
    };
  };

  return {
    getItemProps,
    isDragging: activeIndex !== null,
    didDrag: () => drag.current.moved,
  };
};

// Returns the index whose rect center is nearest the pointer. Null rects
// (non-draggable items, e.g. upload errors) are skipped so they never become a
// drop target. Works for a wrapping grid since it compares both axes.
const getOverIndex = (pointer: Point, rects: (DOMRect | null)[], activeIndex: number): number => {
  let nearest = activeIndex;
  let minDistance = Infinity;
  rects.forEach((rect, index) => {
    if (!rect) {
      return;
    }
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    const distance = (pointer.x - centerX) ** 2 + (pointer.y - centerY) ** 2;
    if (distance < minDistance) {
      minDistance = distance;
      nearest = index;
    }
  });
  return nearest;
};

// Visual offset for a non-active item while dragging: items sitting between the
// active slot and the hovered slot slide one position toward the vacated slot.
const shiftFor = (
  index: number,
  activeIndex: number,
  overIndex: number,
  rects: (DOMRect | null)[]
): Point => {
  const movingDown = overIndex > activeIndex;
  const inRange = movingDown
    ? index > activeIndex && index <= overIndex
    : index < activeIndex && index >= overIndex;
  if (!inRange) {
    return { x: 0, y: 0 };
  }
  const from = rects[index];
  const to = movingDown ? rects[index - 1] : rects[index + 1];
  if (!from || !to) {
    return { x: 0, y: 0 };
  }
  return { x: to.left - from.left, y: to.top - from.top };
};
