import { LayoutGallery } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import { GalleryOptions_Layout_Type } from './../../../ricos-schema/next-schema/index.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { DropdownButton } from './../../../_shared/dropdown-button.js';
import type { SupportedLayouts } from './../../common-types.js';

import { GALLERY_LAYOUT_DROPDOWN, GALLERY_LAYOUT_SETTINGS_MODAL } from '../../consts.js';
import { LAYOUT_DROPDOWN_OPTIONS } from '../layout-dropdown.js';

type Props = {
  toolbarItem: IToolbarItem;
  dataHook?: string;
};

export const GalleryLayoutButton: FC<Props> = ({ dataHook, toolbarItem }) => {
  const { t, isMobile } = useContext(RicosContext) || {};
  const isModalOpen = useModalState(getIsModalOpen(GALLERY_LAYOUT_SETTINGS_MODAL));
  const isDropdownOpen = useModalState(getIsModalOpen(GALLERY_LAYOUT_DROPDOWN));

  const [referenceElement, setReferenceElement] = useState<HTMLElement | null>(null);

  const selectedLayout =
    LAYOUT_DROPDOWN_OPTIONS[toolbarItem?.attributes.layout as SupportedLayouts] ??
    LAYOUT_DROPDOWN_OPTIONS[GalleryOptions_Layout_Type.GRID];

  return (
    <DropdownButton
      dataHook={dataHook}
      active={isDropdownOpen || isModalOpen}
      onClick={() => toolbarItem.commands?.click({ referenceElement, isMobile })}
      ref={setReferenceElement}
      icon={selectedLayout?.icon || LayoutGallery}
      tooltip={t('GalleryPlugin_Layout_Select_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
