import { ProGalleries } from '@wix/wix-ui-icons-common/lazy';

import type { AddButton, RicosServices } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_GALLERY_BUTTON } from './data-hooks.js';
import { handleGalleryUpload } from './handle-gallery-upload.js';
import type { GalleryPluginEditorConfig } from './types.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
  TOOLBARS.MOBILE,
];

export const getAddButtons = (
  config: GalleryPluginEditorConfig | undefined,
  services?: RicosServices
): AddButton[] => {
  return [
    {
      id: Node_Type.GALLERY,
      label: INSERT_PLUGIN_BUTTONS.GALLERY,
      dataHook: INSERT_GALLERY_BUTTON,
      icon: ProGalleries,
      tooltip: 'GalleryPlugin_InsertButton_Tooltip',
      toolbars: toolbarsToAddIn,
      command: ({ publicCommands, referenceElement }) => {
        const { updateService } = services || {};

        if (updateService === undefined) {
          return true;
        }

        if (!services) {
          return false;
        }

        handleGalleryUpload({
          publicCommands,
          services,
          config,
          referenceElement: referenceElement ?? undefined,
        });
        return true;
      },
      menuConfig: {
        tags: 'Gallery_plugin_search_tags',
      },
    },
  ];
};
