import { Image, Loader, Thumbnail } from '@wix/design-system';
import { sdk } from '@wix/image-kit';
import React, { useContext } from 'react';

import { RicosContext } from './../../../../../ricos-context/index.js';
import { ErrorMessageMap } from './../../../../../wix-rich-content-common/lib/error-message-map.js';

import { MEDIA_SETTINGS_SORTABLE_ITEMS } from '../../../../data-hooks.js';
import { GALLERY_ITEMS_TYPES } from '../../../../defaults.js';
import type { GalleryItem } from '../../common-types.js';
import classes from './sortable-item-scss.js';
import type { ItemDragProps } from './use-sortable-grid.js';

const isLocalObjectUrl = (
  item: GalleryItem,
  type: (typeof GALLERY_ITEMS_TYPES)[keyof typeof GALLERY_ITEMS_TYPES]
) => {
  return !!item[type]?.media?.src?.url && item[type]?.media?.src?.url?.indexOf('data:') !== -1;
};

type SortableItemProps = {
  item: GalleryItem;
  dragProps: ItemDragProps;
  didDrag: () => boolean;
  onClick: () => void;
  onDoubleClick: () => void;
  className: string;
};

export const SortableItem: React.FC<SortableItemProps> = ({
  item,
  dragProps,
  didDrag,
  onClick,
  onDoubleClick,
  className,
}) => {
  const { t, environment } = useContext(RicosContext);

  if (item.error) {
    return (
      <div className={className}>
        <Thumbnail
          size="small"
          selected={item.selected}
          onClick={onClick}
          dataHook={MEDIA_SETTINGS_SORTABLE_ITEMS}
          className={classes.itemImage}
          backgroundImage={
            <Loader
              status="error"
              statusMessage={t(
                item.error.key
                  ? ErrorMessageMap[item.error.key as unknown as keyof typeof ErrorMessageMap]
                  : 'UploadFile_Error_Generic_Toast_Multiple'
              )}
            />
          }
        />
      </div>
    );
  }

  const itemType = item?.image ? GALLERY_ITEMS_TYPES.IMAGE : GALLERY_ITEMS_TYPES.VIDEO;

  const prefix = (() => {
    if (Number(item[itemType]?.media?.src?.url?.indexOf('/')) < 0) {
      return 'media/';
    }
    return '';
  })();

  const src =
    itemType === GALLERY_ITEMS_TYPES.VIDEO
      ? (item.video?.thumbnail?.src?.url ?? item.video?.thumbnail?.src?.id)
      : (item.image?.media?.src?.url ?? item.image?.media?.src?.id);

  if (isLocalObjectUrl(item, itemType) || !item[itemType]) {
    return null;
  }

  const url = sdk.getScaleToFillImageURL(
    prefix + src,
    // source dimensions may be unknown; the SDK falls back to the target size
    item[itemType]?.media?.width ?? 0,
    item[itemType]?.media?.height ?? 0,
    100,
    100
  );

  return (
    <div {...dragProps} className={className}>
      <Thumbnail
        size="small"
        selected={item.selected}
        onClick={e => {
          // A click synthesized at the end of a real drag must not toggle selection.
          if (didDrag()) {
            return;
          }
          if (e.detail === 2) {
            onDoubleClick();
            return;
          }
          onClick();
        }}
        dataHook={MEDIA_SETTINGS_SORTABLE_ITEMS}
        className={classes.itemImage}
        backgroundImage={
          src ? ( // src is an empty string during file upload
            <Image
              draggable="false"
              id={item.id}
              role="img"
              aria-label="Gallery Item Thumbnail"
              src={url}
              fit="cover"
              borderRadius={environment === 'liveSite' ? 0 : undefined}
              alt={t('GalleryPlugin_Item_Thumbnail_Alt')}
            />
          ) : (
            <Loader />
          )
        }
      />
    </div>
  );
};
