/**
 * `sizes` tells the browser an upper bound on an image's rendered CSS width so
 * it can pick the smallest sufficient `srcSet` candidate. Overestimating only
 * wastes bytes, but underestimating makes the browser upscale a too-small
 * candidate — so a narrower value is only worth emitting when the layout
 * *guarantees* the bound. Where a cell can grow to the container's full width,
 * `FULL_VIEWPORT_SIZES` remains the correct answer.
 *
 * Values stay in CSS pixels. The browser multiplies them by its own device
 * pixel ratio when matching `w` descriptors, which is why
 * `createGalleryMediaUrl` pins ImageKit's DPR to 1 rather than pre-scaling
 * widths here — doing both would double-count density.
 */
export const FULL_VIEWPORT_SIZES = '100vw';

/**
 * Rounds to hundredths so derived geometry doesn't leak binary floating-point
 * noise (e.g. `340.40000000000003px`) into server-rendered markup or hydration
 * comparisons.
 */
export const roundCssNumber = (value: number) => Math.round(value * 100) / 100;

export const cappedViewportSizes = ({
  maxWidth,
  viewportPercent = 100,
}: {
  maxWidth: number;
  viewportPercent?: number;
}) => `min(${roundCssNumber(maxWidth)}px, ${roundCssNumber(viewportPercent)}vw)`;
