import type { ImgHTMLAttributes } from 'react';

export const GALLERY_TYPE = 'wix-draft-plugin-gallery';

type ScrollingElement = Window | HTMLElement | null;

type DeprecatedProGallerySettings = {
  /** @deprecated No longer supported by the native gallery renderer. This option does nothing. */
  disableSSROpacity?: boolean;
  /** @deprecated No longer supported by the native gallery renderer. This option does nothing. */
  isAccessible?: boolean;
  /** @deprecated No longer supported by the native gallery renderer. This option does nothing. */
  avoidInlineStyles?: boolean;
};

export interface GalleryPluginEditorConfig extends DeprecatedProGallerySettings {
  type: 'gallery';
  /**
   * @deprecated No longer supported by the native gallery renderer. This option does nothing.
   *
   * Gallery doesn't work well when multiple galleries with same nodeId are rendered on the same page.
   * Use this prop to ensure each gallery has a unique id.
   * Value should contain only letters, numbers, hyphens or underscores.
   */
  scopingId?: string;
  /**
   * @deprecated No longer supported by the native gallery renderer. This option does nothing.
   */
  scrollingElement?: (() => ScrollingElement) | ScrollingElement;
}

export type GalleryImageDataAttributes = {
  [Key in `data-${string}`]?: string | boolean;
};

export type GalleryImageAttributes = {
  crossOrigin?: '' | 'anonymous' | 'use-credentials';
  decoding?: 'async' | 'auto' | 'sync';
  fetchPriority?: 'auto' | 'high' | 'low';
  referrerPolicy?: ImgHTMLAttributes<HTMLImageElement>['referrerPolicy'];
} & GalleryImageDataAttributes;

export type GalleryImageProps = (id: string) => GalleryImageAttributes;

export interface GalleryPluginViewerConfig extends DeprecatedProGallerySettings {
  /**
   * @default false
   * When set to true, the gallery items will not expand despite the settings in node data.
   */
  disableExpand?: boolean;
  /**
   * @default true
   * When set to false, lazy loading of gallery items is disabled
   * and all items load immediately.
   */
  lazyLoading?: boolean;
  imageProps?: GalleryImageProps;
  /**
   * @deprecated No longer supported by the native gallery renderer. This option does nothing.
   */
  disableTransition?: boolean;
  /**
   * @deprecated No longer supported by the native gallery renderer. This option does nothing.
   *
   * Gallery doesn't work well when multiple galleries with same nodeId are rendered on the same page.
   * Use this prop to ensure each gallery has a unique id.
   * Value should contain only letters, numbers, hyphens or underscores.
   */
  scopingId?: string;
  /**
   * @deprecated No longer supported by the native gallery renderer. This option does nothing.
   */
  scrollingElement?: (() => ScrollingElement) | ScrollingElement;
}

export type GalleryPluginViewerRuntimeConfig = GalleryPluginViewerConfig & {
  onExpand?: (nodeId: string, itemIndex: number) => void;
};
