// A 2D translation applied to a dragged node while reordering.
export type Transform = { x: number; y: number; scaleX: number; scaleY: number };

// Only the positional fields of a DOMRect are needed for clamping.
type Rect = Pick<DOMRect, 'top' | 'left' | 'right' | 'bottom' | 'width' | 'height'>;

// Clamps a drag transform so the dragged rect stays within boundingRect.
// COPIED FROM https://github.com/clauderic/dnd-kit/blob/%40dnd-kit/utilities%403.2.2/packages/modifiers/src/utilities/restrictToBoundingRect.ts
export function restrictToBoundingRect(
  transform: Transform,
  rect: Rect,
  boundingRect: Rect
): Transform {
  const value = {
    ...transform,
  };

  if (rect.top + transform.y <= boundingRect.top) {
    value.y = boundingRect.top - rect.top;
  } else if (rect.bottom + transform.y >= boundingRect.top + boundingRect.height) {
    value.y = boundingRect.top + boundingRect.height - rect.bottom;
  }

  if (rect.left + transform.x <= boundingRect.left) {
    value.x = boundingRect.left - rect.left;
  } else if (rect.right + transform.x >= boundingRect.left + boundingRect.width) {
    value.x = boundingRect.left + boundingRect.width - rect.right;
  }

  return value;
}
