import { useCallback, useEffect, useState } from 'react';

const SCROLL_EDGE_TOLERANCE = 1;

export type HorizontalScrollEdges = {
  /** No scrollable overflow, so there is nothing for the arrows to page through. */
  allItemsFit: boolean;
  firstEdgeVisible: boolean;
  lastEdgeVisible: boolean;
};

type UseHorizontalScrollEdgesOptions = {
  viewportRef: React.RefObject<HTMLElement>;
  itemCount: number;
  itemIdentity: string;
};

const getInitialEdges = (itemCount: number): HorizontalScrollEdges => ({
  allItemsFit: false,
  firstEdgeVisible: true,
  lastEdgeVisible: itemCount <= 1,
});

const isSameEdges = (left: HorizontalScrollEdges, right: HorizontalScrollEdges) =>
  left.allItemsFit === right.allItemsFit &&
  left.firstEdgeVisible === right.firstEdgeVisible &&
  left.lastEdgeVisible === right.lastEdgeVisible;

/**
 * Tracks how far a horizontal viewport is scrolled, expressed as the three facts
 * the navigation arrows need: whether paging is possible at all, and whether
 * either end is already reached.
 */
export const useHorizontalScrollEdges = ({
  viewportRef,
  itemCount,
  itemIdentity,
}: UseHorizontalScrollEdgesOptions): HorizontalScrollEdges => {
  const [edges, setEdges] = useState(() => getInitialEdges(itemCount));

  const measureEdges = useCallback(() => {
    const viewport = viewportRef.current;
    if (!viewport || viewport.clientWidth <= 0 || viewport.scrollWidth <= 0) {
      return;
    }

    const maximumScroll = Math.max(viewport.scrollWidth - viewport.clientWidth, 0);
    // RTL viewports scroll towards negative `scrollLeft`, so compare distances.
    const scrollPosition = Math.abs(viewport.scrollLeft);
    const measured: HorizontalScrollEdges = {
      allItemsFit: maximumScroll <= SCROLL_EDGE_TOLERANCE,
      firstEdgeVisible: scrollPosition <= SCROLL_EDGE_TOLERANCE,
      lastEdgeVisible: maximumScroll - scrollPosition <= SCROLL_EDGE_TOLERANCE,
    };
    // Every frame of a smooth or momentum scroll lands here, but the arrows only
    // change at the very ends, so keep the previous object and skip the render.
    setEdges(current => (isSameEdges(current, measured) ? current : measured));
  }, [viewportRef]);

  useEffect(() => {
    setEdges(getInitialEdges(itemCount));
  }, [itemCount, itemIdentity]);

  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) {
      return;
    }

    measureEdges();
    viewport.addEventListener('scroll', measureEdges, { passive: true });
    const resizeObserver =
      typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(measureEdges);
    resizeObserver?.observe(viewport);

    return () => {
      viewport.removeEventListener('scroll', measureEdges);
      resizeObserver?.disconnect();
    };
  }, [itemCount, itemIdentity, measureEdges, viewportRef]);

  return edges;
};
