import type { AnchorTarget, RelValue } from './../../ricos-types/index.js';
import { getLinkHrefUrl } from './../../_shared/link/get-link-href-url.js';
import { normalizeHref } from './../../_shared/link/normalize-href.js';
import { getAbsoluteUrl } from './../../_shared/media/get-absolute-url.js';

import { deriveWixMediaId } from './derive-wix-media-id.js';

const FALLBACK_DIMENSION = 1;

/**
 * Structural gallery item input shared by legacy `#ricos-schema` GalleryData
 * and next-schema gallery/image expand paths. Avoids bridge casts between the
 * two schema generations.
 */
export type GalleryItemInput = {
  title?: string;
  altText?: string;
  image?: {
    media?: GalleryMediaInput;
    link?: GalleryLinkInput;
  };
  video?: {
    media?: GalleryMediaInput;
    thumbnail?: GalleryMediaInput;
  };
};

type GalleryMediaInput = {
  src?: {
    url?: string;
    id?: string;
  };
  width?: number;
  height?: number;
};

type GalleryLinkInput = {
  url?: string;
  anchor?: string;
  target?: string;
  rel?: {
    nofollow?: boolean;
    sponsored?: boolean;
    ugc?: boolean;
    noreferrer?: boolean;
  };
};

export type NormalizedGalleryMediaSource = {
  url: string;
  id?: string;
  width?: number;
  height?: number;
};

type NormalizedGalleryItemBase = {
  id: string;
  sourceIndex: number;
  title?: string;
  alt: string;
  width: number;
  height: number;
  disableDownload: boolean;
};

export type NormalizedGalleryItem =
  | (NormalizedGalleryItemBase & {
      type: 'image';
      source: NormalizedGalleryMediaSource;
      link?: {
        url: string;
        target: string;
        rel: string;
      };
    })
  | (NormalizedGalleryItemBase & {
      type: 'video';
      source: NormalizedGalleryMediaSource;
      poster?: NormalizedGalleryMediaSource;
    });

export const normalizeGalleryItems = ({
  items,
  nodeId,
  disableDownload = false,
  relValue,
  anchorTarget,
  baseUrl,
}: {
  items: readonly GalleryItemInput[];
  nodeId: string;
  disableDownload?: boolean;
  relValue?: RelValue;
  anchorTarget?: AnchorTarget;
  baseUrl?: string;
}): NormalizedGalleryItem[] =>
  items.flatMap((item, index): NormalizedGalleryItem[] => {
    const title = item.title || undefined;
    const alt = item.altText || title || '';

    if (item.image?.media) {
      const source = normalizeSource(item.image.media, 'image');
      if (!source) {
        return [];
      }
      const dimensions = normalizeDimensions(item.image.media);

      return [
        {
          type: 'image' as const,
          id: `gallery-item:${nodeId}:${index}`,
          sourceIndex: index,
          title,
          alt,
          width: dimensions.width,
          height: dimensions.height,
          disableDownload,
          source,
          link: normalizeLink(item.image.link, relValue, anchorTarget, baseUrl),
        },
      ];
    }

    if (item.video?.media) {
      const source = normalizeSource(item.video.media, 'video');
      if (!source) {
        return [];
      }
      const dimensions = normalizeDimensions(item.video.media);

      return [
        {
          type: 'video' as const,
          id: `gallery-item:${nodeId}:${index}`,
          sourceIndex: index,
          title,
          alt,
          width: dimensions.width,
          height: dimensions.height,
          disableDownload,
          source,
          poster: item.video.thumbnail ? normalizeSource(item.video.thumbnail, 'image') : undefined,
        },
      ];
    }

    return [];
  });

const normalizeSource = (
  media: GalleryMediaInput,
  type: 'image' | 'video'
): NormalizedGalleryMediaSource | undefined => {
  const sourceValue = media.src?.url || media.src?.id;
  if (!sourceValue?.trim()) {
    return undefined;
  }

  const mediaId = media.src?.id || deriveWixMediaId(sourceValue);

  return {
    url: getAbsoluteUrl(sourceValue, type),
    ...(mediaId ? { id: mediaId } : {}),
    ...(isPositiveFinite(media.width) ? { width: media.width } : {}),
    ...(isPositiveFinite(media.height) ? { height: media.height } : {}),
  };
};

const normalizeDimensions = (media: GalleryMediaInput) => ({
  width: isPositiveFinite(media.width) ? media.width : FALLBACK_DIMENSION,
  height: isPositiveFinite(media.height) ? media.height : FALLBACK_DIMENSION,
});

const isPositiveFinite = (value: number | undefined): value is number =>
  typeof value === 'number' && Number.isFinite(value) && value > 0;

const normalizeLink = (
  link: GalleryLinkInput | undefined,
  relValue: RelValue | undefined,
  anchorTarget: AnchorTarget | undefined,
  baseUrl: string | undefined
) => {
  if (!link) {
    return undefined;
  }

  const normalizedUrl = link.url ? normalizeHref(link.url) : undefined;
  const url =
    normalizedUrl ||
    getLinkHrefUrl(link.anchor ? { anchor: link.anchor } : { url: link.url }, baseUrl);
  if (!url) {
    return undefined;
  }

  const target = link.target ? `_${link.target.toLowerCase()}` : anchorTarget || '_self';
  const rel = link.rel ? normalizeRel(link.rel) : relValue || 'noopener';

  return { url, target, rel };
};

const normalizeRel = (rel: NonNullable<GalleryLinkInput['rel']>) => {
  const values = ['noopener'];
  if (rel.nofollow) {
    values.push('nofollow');
  }
  if (rel.sponsored) {
    values.push('sponsored');
  }
  if (rel.ugc) {
    values.push('ugc');
  }
  if (rel.noreferrer !== false) {
    values.push('noreferrer');
  }
  return values.join(' ');
};
