import { isAbsoluteUrl } from './../../_shared/media/is-absolute-url.js';

/**
 * Resolve a Wix static media file id from a schema src url/id value.
 *
 * Editor/fixture content often stores only a relative file id in `src.url`
 * (e.g. `b17e8c_…~mv2.png`) with no separate `src.id`. ImageKit needs that
 * file id to emit `/v1/fill|fit/…` CDN URLs.
 */
export const deriveWixMediaId = (sourceValue: string): string | undefined => {
  const trimmed = sourceValue.trim();
  if (!trimmed) {
    return undefined;
  }

  if (!isAbsoluteUrl(trimmed)) {
    // Video delivery paths are not static media file ids.
    if (trimmed.startsWith('video/')) {
      return undefined;
    }
    const withoutFolder = trimmed.startsWith('media/') ? trimmed.slice('media/'.length) : trimmed;
    const fileId = withoutFolder.split('/')[0]?.trim();
    return fileId || undefined;
  }

  try {
    const url = new URL(trimmed);
    if (url.hostname !== 'static.wixstatic.com') {
      return undefined;
    }
    const match = url.pathname.match(/^\/media\/([^/]+)/);
    return match?.[1];
  } catch {
    return undefined;
  }
};
