import React from 'react';

import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import classes from './layout-grid-scss.js';
import { MediaCell } from './media-cell.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';
import type { ResolvedGalleryLayout } from './resolve-gallery-layout.js';

type LayoutGridResolved = Extract<ResolvedGalleryLayout, { type: 'GRID' }>;

type LayoutGridProps = {
  items: NormalizedGalleryItem[];
  layout: LayoutGridResolved;
  nodeId: string;
  runtime: GalleryRendererRuntime;
};

const getGridSizes = (columns: number, spacing: number) =>
  columns === 1 ? '100vw' : `calc((100vw - ${(columns - 1) * spacing}px) / ${columns})`;

export const LayoutGrid = ({ items, layout, nodeId, runtime }: LayoutGridProps) => (
  <ul
    className={classes.grid}
    style={
      {
        '--ricos-internal-gallery-grid-columns': layout.columns,
        '--ricos-internal-gallery-grid-ratio': layout.ratio,
        '--ricos-internal-gallery-grid-spacing': `${layout.spacing}px`,
      } as React.CSSProperties
    }
    data-hook="gallery-grid"
  >
    {items.map((item, index) => (
      <MediaCell
        key={item.id}
        item={item}
        nodeId={nodeId}
        presentation={layout.crop === 'FIT' ? 'fit' : 'fill'}
        sizes={getGridSizes(layout.columns, layout.spacing)}
        eager={runtime.lazyLoading === false || index === 0}
        runtime={runtime}
        className={classes.gridCell}
      />
    ))}
  </ul>
);
