import { FormField, SegmentedToggle } from '@wix/design-system';
import { HorizontalRatioSmall, VerticalRatioSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../../../../ricos-context/index.js';
import { GalleryOptions_Layout_Orientation } from './../../../../../ricos-schema/next-schema/index.js';
import type { LogBiFn } from './../../../../../_shared/bi-context-provider/bi-context-provider.js';
import { usePanelContainerElement } from './../../../../../ui-components/index.js';

import { LAYOUT_SETTINGS_IMAGE_ORIENTATION_SEGMENTED_TOGGLE } from '../../../../data-hooks.js';

type Props = {
  onChange: (value: GalleryOptions_Layout_Orientation) => void;
  value: GalleryOptions_Layout_Orientation;
  logBi: LogBiFn;
};

export const ImageOrientationControl: React.FC<Props> = ({ value, onChange, logBi }) => {
  const { t } = useContext(RicosContext);
  const containerEl = usePanelContainerElement();

  return (
    <FormField
      label={t('GallerySettings_Radios_Image_Orientation')}
      infoContent={t('GallerySettings_Radios_Image_Orientation_Tooltip')}
      infoTooltipProps={{
        enterDelay: 300,
        appendTo: containerEl,
      }}
    >
      <SegmentedToggle
        selected={value}
        onClick={(_, value: string) => {
          logBi({ dataHook: LAYOUT_SETTINGS_IMAGE_ORIENTATION_SEGMENTED_TOGGLE, value });
          onChange(value as GalleryOptions_Layout_Orientation);
        }}
        size="small"
        dataHook={LAYOUT_SETTINGS_IMAGE_ORIENTATION_SEGMENTED_TOGGLE}
      >
        <SegmentedToggle.Button
          value={GalleryOptions_Layout_Orientation.COLUMNS}
          prefixIcon={<VerticalRatioSmall />}
        >
          {t('GallerySettings_Radios_Vertical')}
        </SegmentedToggle.Button>
        <SegmentedToggle.Button
          value={GalleryOptions_Layout_Orientation.ROWS}
          prefixIcon={<HorizontalRatioSmall />}
        >
          {t('GallerySettings_Radios_Horizontal')}
        </SegmentedToggle.Button>
      </SegmentedToggle>
    </FormField>
  );
};
