import { ProGalleries, ProGalleriesSmall } from '@wix/wix-ui-icons-common/lazy';

import {
  type EditorPluginCreator,
  Node_Type,
  RicosPluginToolbarNames,
  quickActionsModalSections,
} from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import { galleryConverter } from './gallery-converter.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { handleGalleryUpload } from './handle-gallery-upload.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { GalleryPluginEditorConfig } from './types.js';
import { GALLERY_TYPE } from './types.js';

export const pluginGallery: EditorPluginCreator<GalleryPluginEditorConfig> = config => {
  const pluginConfig: GalleryPluginEditorConfig = {
    type: 'gallery' as const,
    ...DEFAULTS.containerData,
    ...config,
  };
  return {
    config: pluginConfig,
    type: GALLERY_TYPE,
    pmMarkConverters: [],
    pmNodeConverters: [galleryConverter],
    tiptapExtensions,
    getAddButtons: (config, services) => getAddButtons(config, services),
    toolbar: {
      names: [RicosPluginToolbarNames.GALLERY],
      getButtons: (config, services) => getToolbarButtons(config, services),
    },
    getQuickActions: ({ pluginServices, config }) => [
      {
        id: Node_Type.GALLERY,
        title: 'QuickActionsPlugin_ActionTitle_Gallery',
        icon: pluginServices?.context.isMobile ? ProGalleries : ProGalleriesSmall,
        section: quickActionsModalSections.Media,
        tags: ['gallery', 'photo', 'album', 'picture', 'collection', 'slideshow', 'portfolio'],
        command: ({ publicCommands }) => {
          handleGalleryUpload({ publicCommands, services: pluginServices, config });
        },
      },
    ],
  };
};
