import { FormField, SegmentedToggle } from '@wix/design-system';
import { FocusSmall, SizeAndRatioSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../../../../ricos-context/index.js';
import { GalleryOptions_ItemStyle_Crop } from './../../../../../ricos-schema/next-schema/index.js';
import type { LogBiFn } from './../../../../../_shared/bi-context-provider/bi-context-provider.js';
import { usePanelContainerElement } from './../../../../../ui-components/index.js';

import { LAYOUT_SETTINGS_THUMBNAIL_CROP_SEGMENTED_TOGGLE } from '../../../../data-hooks.js';

type Props = {
  onChange: (value: GalleryOptions_ItemStyle_Crop) => void;
  value: GalleryOptions_ItemStyle_Crop;
  logBi: LogBiFn;
};

export const ThumbnailCropControl: React.FC<Props> = ({ value, onChange, logBi }) => {
  const { t } = useContext(RicosContext);
  const containerEl = usePanelContainerElement();

  return (
    <FormField
      label={t('GallerySettings_Radios_Thumbnail_Resize')}
      infoContent={t('GallerySettings_Radios_Thumbnail_Resize_Tooltip')}
      infoTooltipProps={{
        enterDelay: 300,
        appendTo: containerEl,
      }}
    >
      <SegmentedToggle
        selected={value}
        onClick={(_, value) => {
          logBi({ dataHook: LAYOUT_SETTINGS_THUMBNAIL_CROP_SEGMENTED_TOGGLE, value });
          onChange(value as GalleryOptions_ItemStyle_Crop);
        }}
        size="small"
        dataHook={LAYOUT_SETTINGS_THUMBNAIL_CROP_SEGMENTED_TOGGLE}
      >
        <SegmentedToggle.Button
          value={GalleryOptions_ItemStyle_Crop.FILL}
          prefixIcon={<FocusSmall />}
        >
          {t('GallerySettings_Radios_Crop')}
        </SegmentedToggle.Button>
        <SegmentedToggle.Button
          value={GalleryOptions_ItemStyle_Crop.FIT}
          prefixIcon={<SizeAndRatioSmall />}
        >
          {t('GallerySettings_Radios_Fit')}
        </SegmentedToggle.Button>
      </SegmentedToggle>
    </FormField>
  );
};
