import { AddItem, FileUpload } from '@wix/design-system';
import React from 'react';

import type { LogBiFn } from './../../../../../_shared/bi-context-provider/bi-context-provider.js';

import {
  MEDIA_SETTINGS_ADD_MEDIA_INPUT,
  MEDIA_SETTINGS_SORTABLE_ITEMS_CONTAINER,
} from '../../../../data-hooks.js';
import type { GalleryItem, SelectFileFn } from '../../common-types.js';
import { SortableItem } from './sortable-item.js';
import classes from './sortable-list-scss.js';
import { useSortableGrid } from './use-sortable-grid.js';

type SortableListProps = {
  items: GalleryItem[];
  onItemClick: (id: number) => void;
  onItemDoubleClick: (id: number) => void;
  onFileSelect: SelectFileFn;
  onSortEnd: ({ oldIndex, newIndex }: { oldIndex: number; newIndex: number }) => void;
  logBi: LogBiFn;
};

export const SortableList: React.FC<SortableListProps> = ({
  items,
  onItemClick,
  onItemDoubleClick,
  onFileSelect,
  onSortEnd,
  logBi,
}: SortableListProps) => {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const { getItemProps, didDrag } = useSortableGrid({
    itemCount: items.length,
    getContainerRect: () => containerRef.current?.getBoundingClientRect(),
    onSortEnd: ({ oldIndex, newIndex }) => {
      logBi({ dataHook: MEDIA_SETTINGS_SORTABLE_ITEMS_CONTAINER, value: newIndex });
      onSortEnd({ oldIndex, newIndex });
    },
  });

  return (
    <div className={classes.container} ref={containerRef}>
      <FileUpload
        multiple
        accept=".jpeg,.gif,.png"
        onChange={() => {}}
        dataHook={MEDIA_SETTINGS_ADD_MEDIA_INPUT}
        className={classes.fileUpload}
      >
        {() => <AddItem theme="image" onClick={() => onFileSelect?.()} />}
      </FileUpload>
      {items.map((item, index) => (
        <SortableItem
          key={item.id}
          item={item}
          dragProps={getItemProps(index)}
          didDrag={didDrag}
          onClick={() => onItemClick(index)}
          onDoubleClick={() => onItemDoubleClick(index)}
          className={classes.item}
        />
      ))}
    </div>
  );
};
