import { ManagePhotos } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { ToolbarButton } from './../../../_shared/toolbar-button/toolbar-button.js';

import { GALLERY_MEDIA_SETTINGS_MODAL } from '../../consts.js';

interface Props {
  toolbarItem: IToolbarItem;
  dataHook?: string;
}

export const GalleryManageMediaButton: FC<Props> = ({ toolbarItem, dataHook }) => {
  const { isMobile, t } = useContext(RicosContext) || {};
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const isModalOpen = useModalState(getIsModalOpen(GALLERY_MEDIA_SETTINGS_MODAL));
  const onClick = toolbarItem.commands.click;

  return (
    <ToolbarButton
      prefix={ManagePhotos}
      label={t('GallerySettings_Toolbar_Button_MangeMedia')}
      onClick={() => onClick({ isMobile, referenceElement })}
      dataHook={dataHook}
      ariaLabel={t('ManageMediaButton_Tooltip')}
      ref={setReferenceElement}
      active={isModalOpen}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
