import React from 'react';

import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import classes from './layout-panorama-scss.js';
import { MediaCell } from './media-cell.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';
import type { ResolvedGalleryLayout } from './resolve-gallery-layout.js';

type LayoutPanoramaResolved = Extract<ResolvedGalleryLayout, { type: 'PANORAMA' }>;

type LayoutPanoramaProps = {
  items: NormalizedGalleryItem[];
  layout: LayoutPanoramaResolved;
  nodeId: string;
  runtime: GalleryRendererRuntime;
};

export const LayoutPanorama = ({ items, layout, nodeId, runtime }: LayoutPanoramaProps) => (
  <ul
    className={classes.panorama}
    style={
      {
        '--ricos-internal-gallery-panorama-spacing': `${layout.spacing}px`,
      } as React.CSSProperties
    }
    data-hook="gallery-panorama"
  >
    {items.map((item, index) => (
      <MediaCell
        key={item.id}
        item={item}
        nodeId={nodeId}
        presentation="intrinsic"
        sizes="100vw"
        eager={runtime.lazyLoading === false || index === 0}
        runtime={runtime}
      />
    ))}
  </ul>
);
