import type { GalleryOptions } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

const DEFAULT_SPACING = 5;
const MIN_SPACING = 0;
const MAX_SPACING = 100;
const DEFAULT_TARGET_SIZE = 300;
const MIN_TARGET_SIZE = 10;
const MAX_TARGET_SIZE = 1000;
const DEFAULT_GRID_COLUMNS = 3;
const MIN_GRID_COLUMNS = 1;
const MAX_GRID_COLUMNS = 5;
const DEFAULT_GRID_RATIO = 1;
const DEFAULT_SLIDER_RATIO = 16 / 9;
const SUPPORTED_RATIOS = new Set([16 / 9, 4 / 3, 1, 3 / 4, 9 / 16]);

type Crop = 'FILL' | 'FIT';
type Orientation = 'ROWS' | 'COLUMNS';
type ThumbnailPlacement = 'TOP' | 'RIGHT' | 'BOTTOM' | 'LEFT' | 'NONE';

export type ResolvedGalleryLayout =
  | { type: 'PANORAMA'; spacing: number }
  | { type: 'GRID'; columns: number; ratio: number; crop: Crop; spacing: number }
  | { type: 'FULLSIZE' }
  | { type: 'SLIDER'; ratio: number; crop: Crop; spacing: number }
  | { type: 'COLUMN'; spacing: number }
  | { type: 'THUMBNAIL'; placement: ThumbnailPlacement; spacing: number }
  | {
      type: 'MASONRY';
      orientation: Orientation;
      targetSize: number;
      spacing: number;
      horizontalScroll: boolean;
    };

export const resolveGalleryLayout = ({
  options,
  isMobile,
}: {
  options?: GalleryOptions;
  isMobile: boolean;
}): ResolvedGalleryLayout => {
  switch (options?.layout?.type) {
    case 'PANORAMA':
      return {
        type: 'PANORAMA',
        spacing: resolveClampedNumber(options.item?.spacing, DEFAULT_SPACING, 0, 100),
      };
    case 'FULLSIZE':
    case 'SLIDESHOW':
      return { type: 'FULLSIZE' };
    case 'SLIDER':
      return {
        type: 'SLIDER',
        ratio: resolveRatio(options.item?.ratio, DEFAULT_SLIDER_RATIO),
        crop: resolveCrop(options.item?.crop, 'FIT'),
        spacing: resolveSpacing(options.item?.spacing),
      };
    case 'COLUMN':
      return {
        type: 'COLUMN',
        spacing: resolveSpacing(options.item?.spacing),
      };
    case 'THUMBNAIL':
      return {
        type: 'THUMBNAIL',
        placement: resolveThumbnailPlacement(options.thumbnails?.placement),
        spacing: resolveClampedInteger(
          options.thumbnails?.spacing,
          DEFAULT_SPACING,
          MIN_SPACING,
          MAX_SPACING
        ),
      };
    case 'MASONRY':
      return {
        type: 'MASONRY',
        orientation: resolveOrientation(options.layout.orientation, 'ROWS'),
        targetSize: resolveTargetSize(options.item?.targetSize),
        spacing: resolveSpacing(options.item?.spacing),
        horizontalScroll: options.layout.horizontalScroll === true,
      };
    case 'COLLAGE':
      return {
        type: 'MASONRY',
        horizontalScroll: options.layout.horizontalScroll === true,
        orientation: resolveOrientation(options.layout.orientation, 'COLUMNS'),
        targetSize: resolveTargetSize(options.item?.targetSize),
        spacing: resolveSpacing(options.item?.spacing),
      };
    case 'GRID':
    case 'MAGIC':
    default:
      return resolveGrid(options, isMobile);
  }
};

const resolveGrid = (options: GalleryOptions | undefined, isMobile: boolean) => {
  const desktopColumns = resolveGridColumns(options?.layout?.numberOfColumns);
  const mobileColumns = resolveGridColumns(options?.layout?.mobileNumberOfColumns, desktopColumns);

  return {
    type: 'GRID' as const,
    columns: isMobile ? mobileColumns : desktopColumns,
    ratio: resolveRatio(options?.item?.ratio, DEFAULT_GRID_RATIO),
    crop: resolveCrop(options?.item?.crop, 'FILL'),
    spacing: resolveSpacing(options?.item?.spacing),
  };
};

const resolveGridColumns = (value: number | undefined, fallback = DEFAULT_GRID_COLUMNS) =>
  typeof value === 'number' &&
  Number.isInteger(value) &&
  value >= MIN_GRID_COLUMNS &&
  value <= MAX_GRID_COLUMNS
    ? value
    : fallback;

const resolveRatio = (value: number | undefined, fallback: number) =>
  typeof value === 'number' && SUPPORTED_RATIOS.has(value) ? value : fallback;

const resolveCrop = (value: unknown, fallback: Crop): Crop =>
  value === 'FILL' || value === 'FIT' ? value : fallback;

const resolveOrientation = (value: unknown, fallback: Orientation): Orientation =>
  value === 'ROWS' || value === 'COLUMNS' ? value : fallback;

const resolveThumbnailPlacement = (value: unknown): ThumbnailPlacement =>
  value === 'TOP' || value === 'RIGHT' || value === 'BOTTOM' || value === 'LEFT' || value === 'NONE'
    ? value
    : 'BOTTOM';

const resolveSpacing = (value: number | undefined) =>
  resolveClampedNumber(value, DEFAULT_SPACING, MIN_SPACING, MAX_SPACING);

const resolveTargetSize = (value: number | undefined) =>
  resolveClampedNumber(value, DEFAULT_TARGET_SIZE, MIN_TARGET_SIZE, MAX_TARGET_SIZE);

const resolveClampedInteger = (
  value: number | undefined,
  fallback: number,
  minimum: number,
  maximum: number
) =>
  typeof value === 'number' && Number.isFinite(value)
    ? Math.min(maximum, Math.max(minimum, Math.trunc(value)))
    : fallback;

const resolveClampedNumber = (
  value: number | undefined,
  fallback: number,
  minimum: number,
  maximum: number
) =>
  typeof value === 'number' && Number.isFinite(value)
    ? Math.min(maximum, Math.max(minimum, value))
    : fallback;
