import classNames from 'classnames';
import React from 'react';

import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import { cappedViewportSizes, roundCssNumber } from './gallery-image-sizes.js';
import { getIntrinsicPresentation, HorizontalTrack } from './horizontal-track.js';
import classes from './layout-masonry-scss.js';
import { MediaCell } from './media-cell.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';
import type { ResolvedGalleryLayout } from './resolve-gallery-layout.js';

type LayoutMasonryResolved = Extract<ResolvedGalleryLayout, { type: 'MASONRY' }>;

type LayoutMasonryProps = {
  items: NormalizedGalleryItem[];
  layout: LayoutMasonryResolved;
  nodeId: string;
  runtime: GalleryRendererRuntime;
};

// CSS flex can only wrap eagerly at each row's preferred basis, then stretch
// the row to fill the remaining width. Without DOM measurement we cannot
// re-pack rows the way ProGallery's JS layouter does, so a basis at the full
// target size wraps too late and the stretch overshoots the target row height.
// Shrinking the basis by this factor packs more items per row so the stretched
// result lands near the target, while keeping
// `--ricos-internal-gallery-masonry-target-size` itself equal to the resolved,
// document-driven target size.
const ROWS_PACKING_FACTOR = 0.8;

// Upper bound on how far a row may stretch, as a multiple of the target size.
// Rows always justify to the container's full width, so a row holding few items
// — a trailing row after a wrap, or a short gallery that never wraps at all —
// would grow without limit. Capping each cell at the ratio-scaled bound keeps
// such a row at most this many times the target row height.
const MAX_ROW_STRETCH = 1.5;

// Container width below which `layout-masonry.scss` releases the cap so a row
// that wrapped down to a single item still fills the block. Mirrors the
// `container-max-width` default in `mixins.scss`; the value is needed here too
// because a released cell can be as wide as its container, which widens the
// bound the `sizes` attribute has to promise.
const CAP_RELEASE_WIDTH = 480;

// Fixed block size of the legacy horizontal-scroll compatibility flow. Exposed
// to CSS as a custom property so `layout-masonry.scss` and the `sizes` bound
// below read the same value.
const HORIZONTAL_BLOCK_SIZE = 500;

const toRowBasisPx = (targetSize: number) =>
  `${roundCssNumber(targetSize * ROWS_PACKING_FACTOR)}px`;

const toRowMaxBasisPx = (targetSize: number) => `${roundCssNumber(targetSize * MAX_ROW_STRETCH)}px`;

const ratioOf = (item: NormalizedGalleryItem) => item.width / item.height;

// Vertical Rows cells justify to the container's full width, bounded by the cap
// in `layout-masonry.scss` — except below CAP_RELEASE_WIDTH, where the released
// cell fills a container that is itself no wider than that. Only the looser of
// the two bounds is safe to promise, and neither can exceed the viewport.
const toRowsSizes = (targetSize: number, item: NormalizedGalleryItem) => {
  const cap = roundCssNumber(targetSize * MAX_ROW_STRETCH * ratioOf(item));

  return `min(100vw, max(${cap}px, ${CAP_RELEASE_WIDTH}px))`;
};

const horizontalRootStyle = {
  '--ricos-internal-gallery-masonry-horizontal-block-size': `${HORIZONTAL_BLOCK_SIZE}px`,
} as React.CSSProperties;

const getCellSizes = (layout: LayoutMasonryResolved, item: NormalizedGalleryItem) => {
  if (layout.orientation === 'COLUMNS') {
    // `column-width` is a minimum and the used column count is floored, so a
    // column is at its widest just below the width where one more column would
    // fit — that column's target size plus the gap it would have needed.
    return cappedViewportSizes({ maxWidth: 2 * layout.targetSize + layout.spacing });
  }

  if (layout.horizontalScroll) {
    // Horizontal Rows cells are `flex: 0 0 auto` at a fixed block size, so the
    // item ratio determines the rendered width exactly.
    return cappedViewportSizes({
      maxWidth: Math.min(layout.targetSize, HORIZONTAL_BLOCK_SIZE) * ratioOf(item),
    });
  }

  return toRowsSizes(layout.targetSize, item);
};

const getCellStyle = (item: NormalizedGalleryItem) =>
  ({
    '--ricos-internal-gallery-masonry-item-ratio': ratioOf(item),
  }) as React.CSSProperties;

export const LayoutMasonry = ({ items, layout, nodeId, runtime }: LayoutMasonryProps) => {
  const style = {
    '--ricos-internal-gallery-masonry-target-size': `${layout.targetSize}px`,
    '--ricos-internal-gallery-masonry-row-basis': toRowBasisPx(layout.targetSize),
    '--ricos-internal-gallery-masonry-row-max-basis': toRowMaxBasisPx(layout.targetSize),
    '--ricos-internal-gallery-masonry-spacing': `${layout.spacing}px`,
  } as React.CSSProperties;
  const listClassName = classNames(
    classes.masonry,
    layout.orientation === 'COLUMNS' ? classes.columns : classes.rows,
    layout.horizontalScroll && classes.horizontal
  );
  const getSizes = (item: NormalizedGalleryItem) => getCellSizes(layout, item);

  if (layout.horizontalScroll) {
    return (
      <HorizontalTrack
        items={items}
        nodeId={nodeId}
        runtime={runtime}
        rootClassName={classes.horizontalRoot}
        rootStyle={horizontalRootStyle}
        rootProps={{
          'data-hook': 'gallery-masonry',
          'data-orientation': layout.orientation,
          'data-flow': 'HORIZONTAL',
        }}
        viewportClassName={classes.horizontalViewport}
        trackClassName={listClassName}
        trackStyle={style}
        cellClassName={classes.masonryCell}
        getPresentation={getIntrinsicPresentation}
        getCellStyle={getCellStyle}
        getSizes={getSizes}
      />
    );
  }

  return (
    <ul
      className={listClassName}
      style={style}
      data-hook="gallery-masonry"
      data-orientation={layout.orientation}
      data-flow="VERTICAL"
    >
      {items.map((item, index) => (
        <MediaCell
          key={item.id}
          item={item}
          nodeId={nodeId}
          presentation="intrinsic"
          sizes={getSizes(item)}
          eager={runtime.lazyLoading === false || index === 0}
          runtime={runtime}
          className={classes.masonryCell}
          style={getCellStyle(item)}
        />
      ))}
    </ul>
  );
};
