import React from 'react';

import type { NormalizedGalleryItem } from '../media/normalize-gallery-items.js';
import { getFillPresentation, HorizontalTrack } from './horizontal-track.js';
import classes from './layout-column-scss.js';
import type { GalleryRendererRuntime } from './native-gallery-types.js';
import type { ResolvedGalleryLayout } from './resolve-gallery-layout.js';

type LayoutColumnResolved = Extract<ResolvedGalleryLayout, { type: 'COLUMN' }>;

type LayoutColumnProps = {
  items: NormalizedGalleryItem[];
  layout: LayoutColumnResolved;
  nodeId: string;
  runtime: GalleryRendererRuntime;
};

const CELL_WIDTH = '175px';

const ROOT_PROPS = { 'data-hook': 'gallery-column' } as const;

const getCellSizes = () => CELL_WIDTH;

export const LayoutColumn = ({ items, layout, nodeId, runtime }: LayoutColumnProps) => {
  const columnStyle = {
    '--ricos-internal-gallery-column-spacing': `${layout.spacing}px`,
  } as React.CSSProperties;

  return (
    <HorizontalTrack
      items={items}
      nodeId={nodeId}
      runtime={runtime}
      rootClassName={classes.column}
      rootStyle={columnStyle}
      rootProps={ROOT_PROPS}
      viewportClassName={classes.columnViewport}
      trackClassName={classes.columnTrack}
      cellClassName={classes.columnCell}
      getPresentation={getFillPresentation}
      getSizes={getCellSizes}
    />
  );
};
