import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { GalleryData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { EditorBaseUrlContext } from './../../_shared/editor-base-url/editor-base-url-context.js';
import { Loader, MediaItemErrorMsg } from './../../ui-components/index.js';

import styles from '../statics/styles/gallery-component-scss.js';
import type { GalleryPluginViewerRuntimeConfig } from '../types.js';
import { GalleryViewer } from '../viewer/gallery-viewer.js';

const renderMobileNativeLoader = ({ url }: $TSFixMe) =>
  url ? null : (
    <div className={styles.mobileNativeLoaderContainer}>
      <Loader type={'mini'} disableProgress />
    </div>
  );

const editorPreviewSettings: GalleryPluginViewerRuntimeConfig = {};

export const Gallery: React.FC<PluginProps> = ({ componentData, node }) => {
  const { error } = node.attrs;
  const { t } = useContext(RicosContext);
  const { baseUrl } = useContext(EditorBaseUrlContext);
  const anchorTarget = '';
  const relValue = '';

  return (
    <>
      <GalleryViewer
        componentData={componentData as GalleryData}
        nodeId={node.attrs.id}
        settings={editorPreviewSettings}
        anchorTarget={anchorTarget}
        relValue={relValue}
        itemOverlayElement={renderMobileNativeLoader}
        baseUrl={baseUrl}
      />
      {!error && node.attrs.loading && <Loader type={'medium'} />}
      {error && <MediaItemErrorMsg error={error} t={t} />}
    </>
  );
};
