import type {
  ImageComponentData,
  UpdateEntityFileSelectFunc,
  VideoComponentData,
} from './../ricos-content/index.js';
import type { PluginServices } from './../ricos-plugins/editor-plugins.js';
import { GalleryOptions_Layout_Type } from './../ricos-schema/next-schema/index.js';
import type { IMessage, PublicCommands } from './../ricos-types/index.js';
import { type MediaUploadFn, createMediaUploadFn } from './../_shared/create-media-upload-fn.js';
import { getHighestQualityVideo } from './../_shared/get-highest-quality-video.js';
import { logInvariant } from './../_shared/log-invariant.js';
import { createOpenMediaManagerFn } from './../_shared/media-manager/create-open-media-manager-fn.js';
import { MediaManagerMediaType } from './../_shared/media-manager/types.js';
import type { PickMediaFn } from './../_shared/media/pick-media.js';
import type {
  PickMediaImageData,
  PickMediaVideoData,
  PublicPickMedia,
} from './../_shared/media/public-pick-media.js';
import type { PmGalleryNode } from './../_shared/pm-node-types.js';
import { unreachable } from './../_shared/uncreachable.js';
import { upload } from './../_shared/upload/upload.js';
import { layoutRicosData } from './/layout-data-provider.js';

import { fileInputAccept } from './consts.js';
import type { GalleryPluginEditorConfig } from './types.js';
import { GALLERY_TYPE } from './types.js';

type FileState = { itemIndex: number };
type GalleryItem = NonNullable<PmGalleryNode['attrs']['items']>[0];

const getGalleryAttributes = ({
  uploadedData,
  componentData,
  fileState,
}: {
  uploadedData: ImageComponentData | VideoComponentData | PickMediaImageData | PickMediaVideoData;
  componentData: PmGalleryNode['attrs'];
  fileState?: FileState;
}) => {
  const fileType = (uploadedData as VideoComponentData).thumbnail ? 'video' : 'image';

  let galleryItem: NonNullable<PmGalleryNode['attrs']['items']>[0];
  if (fileType === 'video') {
    galleryItem = galleryVideoBuilder(uploadedData as VideoComponentData | PickMediaVideoData);
  } else {
    galleryItem = galleryImageBuilder(uploadedData as ImageComponentData | PickMediaImageData);
  }
  const itemPos: number | undefined = fileState?.itemIndex as number | undefined;
  const newComponentData = setItemInGallery(galleryItem, componentData, itemPos);
  return {
    ...newComponentData,
    error: null,
  };
};

const getGalleryErrorAttributes = (
  error: IMessage,
  componentData: PmGalleryNode['attrs'],
  fileState?: FileState
) => {
  const itemPos = fileState ? fileState.itemIndex : undefined;
  const galleryItem = {
    error,
    ...(itemPos !== undefined ? (componentData.items?.[itemPos] ?? {}) : {}),
  };
  const newComponentData = setItemInGallery(galleryItem as GalleryItem, componentData, itemPos);
  return {
    ...newComponentData,
  };
};

const setItemInGallery = (
  item: GalleryItem,
  componentData: PmGalleryNode['attrs'],
  itemPos?: number
): PmGalleryNode['attrs'] => {
  let { items } = componentData;
  if (typeof itemPos === 'undefined') {
    items = [...(items ?? []), item];
  } else {
    items = items ? [...items] : [];
    items[itemPos] = item;
  }
  return { ...componentData, items };
};

const isPickMediaImageType = (
  data: ImageComponentData | PickMediaImageData
): data is PickMediaImageData => 'type' in data && data.type === 'image';

const galleryImageBuilder = (img: ImageComponentData | PickMediaImageData) => {
  if (isPickMediaImageType(img)) {
    return {
      image: {
        media: {
          src: img.src,
          height: img.height,
          width: img.width,
        },
      },
      loading: false,
    };
  }

  return {
    image: {
      media: {
        src: { url: img.file_name },
        height: img.height,
        width: img.width,
      },
    },
    loading: false,
  };
};

const isPickMediaVideoType = (
  data: VideoComponentData | PickMediaVideoData
): data is PickMediaVideoData => 'type' in data && data.type === 'video';

const galleryVideoBuilder = (video: VideoComponentData | PickMediaVideoData) => {
  if (isPickMediaVideoType(video)) {
    return {
      video: {
        media: {
          src: video.src,
          height: video.height,
          width: video.width,
        },
        thumbnail: {
          src: video.thumbnail.src,
          width: video.thumbnail.width,
          height: video.thumbnail.height,
        },
      },
      loading: false,
    };
  }

  const {
    thumbnail: { pathname: url, width, height },
  } = video;
  return {
    video: {
      media: {
        src: { url: video.pathname },
        height: video.height || height,
        width: video.width || width,
      },
      thumbnail: {
        src: { url },
        width,
        height,
      },
    },
    loading: false,
  };
};

const getGalleryFileType = (type: string) => {
  return type.match('image/*') ? 'image' : type.match('video/*') ? 'video' : '';
};

const createMediaFileSelectionFn = (services: Pick<PluginServices, 'wixInstance' | 'modals'>) => {
  const openMediaManager = createOpenMediaManagerFn(services.modals);
  if (!openMediaManager) {
    return undefined;
  }

  return (
    updateEntity: UpdateEntityFileSelectFunc<(ImageComponentData | VideoComponentData)[]>,
    options: { index: number | undefined; multiple: boolean },
    onCancel: () => void
  ) =>
    openMediaManager({
      mediaType: MediaManagerMediaType.ALL_MEDIA,
      appDefId: services.wixInstance().appDefId,
      isMultiSelect: options.multiple,
    })
      .then(items => {
        const mediaData = items.reduce<(ImageComponentData | VideoComponentData)[]>(
          (acc, media) => {
            switch (media.mediaType) {
              case 'video': {
                const { title, height, width } = media;
                const thumbnail = media.fileOutput?.image[0];
                const { url: pathname } = getHighestQualityVideo(media.fileOutput.video);
                return [
                  ...acc,
                  {
                    pathname,
                    height,
                    width,
                    title,
                    thumbnail: {
                      pathname: thumbnail.url,
                      height: thumbnail.height,
                      width: thumbnail.width,
                    },
                  } as VideoComponentData,
                ];
              }
              case 'picture': {
                const { id, fileName, title, height, width } = media;
                return [
                  ...acc,
                  {
                    id,
                    height,
                    width,
                    original_file_name: title,
                    file_name: fileName,
                  } as ImageComponentData,
                ];
              }
              default:
                return acc;
            }
          },
          []
        );

        updateEntity({
          data: mediaData,
          // @ts-expect-error
          index: options.index,
        });
      })
      .catch(onCancel);
};

export const getGalleryPickMedia = ({
  services,
  handleFileUpload,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  handleFileUpload: MediaUploadFn;
}): PickMediaFn | PublicPickMedia['pickGallery'] => {
  const devPickMedia = services.devService().pickMedia;
  const editorPickMedia = services.editorProps.pickMedia?.pickGallery;
  const handleFileSelection =
    services.devService().handleFileSelection ?? createMediaFileSelectionFn(services);

  return devPickMedia
    ? devPickMedia
    : editorPickMedia
      ? editorPickMedia
      : handleFileSelection
        ? async ({ multiple }: Parameters<PickMediaFn>[0]) => {
            try {
              const data = await new Promise<(ImageComponentData | VideoComponentData)[]>(
                (resolve, reject) =>
                  handleFileSelection(
                    ({ data }) => resolve(data),
                    { multiple, index: undefined },
                    reject
                  )
              );
              return { type: 'ready-media' as const, media: data instanceof Array ? data : [data] };
            } catch {
              return { type: 'cancel' as const };
            }
          }
        : async ({ mimeType, multiple }: Parameters<PickMediaFn>[0]) => {
            const files =
              (await services.uploadService?.selectFiles({ accept: mimeType, multiple })) ?? [];
            return { type: 'file' as const, file: files, customUploadFn: handleFileUpload };
          };
};

const DEFAULT_DATA = {
  items: [],
  options: layoutRicosData[GalleryOptions_Layout_Type.GRID],
};

export const handleGalleryUpload = async ({
  publicCommands,
  services,
  config: _config,
  nodeId,
  fileState,
  referenceElement,
}: {
  publicCommands: PublicCommands;
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  config?: GalleryPluginEditorConfig;
  nodeId?: string;
  fileState?: { itemIndex: number };
  referenceElement?: HTMLElement;
}) => {
  const accept = fileInputAccept;
  const multiple = !fileState;
  const handleFileUpload = services.devService().handleFileUpload ?? createMediaUploadFn(services);

  const pickMedia = getGalleryPickMedia({ services, handleFileUpload });

  const result = await pickMedia({ mimeType: accept, multiple });

  switch (result.type) {
    case 'ready-media': {
      if (!nodeId) {
        const componentData = result.media.reduce(
          (acc, item, index) => {
            return getGalleryAttributes({
              uploadedData: item as ImageComponentData | VideoComponentData,
              componentData: acc,
              fileState: { itemIndex: index },
            });
          },
          { ...DEFAULT_DATA } as unknown as PmGalleryNode['attrs']
        );

        publicCommands.insertBlockWithBlankLines(GALLERY_TYPE, componentData, {
          updateSelection: true,
        });
        return;
      }

      const rootItemsLength =
        (publicCommands?.getBlockComponentData(nodeId) as PmGalleryNode['attrs'])?.items?.length ||
        0;

      result.media.forEach((item, index) => {
        setTimeout(() => {
          const componentData = publicCommands?.getBlockComponentData(
            nodeId
          ) as PmGalleryNode['attrs'];

          publicCommands.setBlock(
            nodeId,
            GALLERY_TYPE,
            getGalleryAttributes({
              uploadedData: item as ImageComponentData | VideoComponentData,
              componentData,
              fileState: fileState ? fileState : { itemIndex: rootItemsLength + index },
            })
          );
        });
      });
      return;
    }
    case 'file': {
      const files = result.file;

      const targetNodeId =
        nodeId ??
        publicCommands.insertBlockWithBlankLines(GALLERY_TYPE, DEFAULT_DATA, {
          updateSelection: true,
        });

      const rootItemsLength =
        (publicCommands?.getBlockComponentData(targetNodeId) as PmGalleryNode['attrs'])?.items
          ?.length || 0;

      await Promise.all(
        files.map(async (_file, index) => {
          const file = new File([_file], _file.name, { type: _file.type });
          const trackBi = services.uploadService.trackUploadBi(GALLERY_TYPE, file.size, file.name);
          const itemIndex = fileState ? fileState.itemIndex : rootItemsLength + index;
          try {
            const componentData = publicCommands?.getBlockComponentData(targetNodeId);

            const fileType = getGalleryFileType(file.type);
            const galleryItem = { [fileType]: { media: { src: { url: '' } } }, loading: true };
            const newComponentData = setItemInGallery(galleryItem, componentData, itemIndex);

            publicCommands?.setBlock(targetNodeId, GALLERY_TYPE, {
              ...newComponentData,
              loading: true,
              error: null,
            });

            trackBi?.start();
            const uploadFn = result.customUploadFn || handleFileUpload;

            if (!uploadFn) {
              logInvariant(Error('No upload function provided'));
              throw new Error('No upload function provided');
            }

            const uploadedFile = await upload(uploadFn, file);

            publicCommands?.setBlock(targetNodeId, GALLERY_TYPE, {
              ...getGalleryAttributes({
                uploadedData: uploadedFile.data as
                  | ImageComponentData
                  | VideoComponentData
                  | PickMediaImageData
                  | PickMediaVideoData,
                componentData: publicCommands?.getBlockComponentData(
                  targetNodeId
                ) as PmGalleryNode['attrs'],
                fileState: { itemIndex },
              }),
            } satisfies PmGalleryNode['attrs']);

            trackBi?.success();
          } catch (error: any) {
            const componentData = publicCommands?.getBlockComponentData(targetNodeId);
            publicCommands?.setBlock(
              targetNodeId,
              GALLERY_TYPE,
              getGalleryErrorAttributes(error, componentData, { itemIndex })
            );

            trackBi?.error(error);
            services.uploadService.notifyError(error);
          }
        })
      );

      const componentData = publicCommands?.getBlockComponentData(targetNodeId);
      publicCommands?.setBlock(targetNodeId, GALLERY_TYPE, {
        ...componentData,
        loading: false,
      });

      return;
    }
    case 'cancel': {
      services.modals.notifyExternalModalClosed({ focusReturnElement: referenceElement });
      return;
    }
    default: {
      console.error(unreachable(result));
      return;
    }
  }
};
