import { definePmNodeConverter } from './../pm-converters/types.js';
import type { GalleryData, Link } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';
import { fromTiptapLinkConverter } from './../_shared/link/link-converters.js';
import type { PmGalleryNode } from './../_shared/pm-node-types.js';

export const galleryConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.GALLERY],
    convert: node => ({
      type: Node_Type.GALLERY,
      attrs: {
        ...node.galleryData,
        id: node.id,
      },
    }),
  },
  fromPm: {
    types: [Node_Type.GALLERY],
    convert: node => {
      const { id, animation, ...data } = node.attrs || {};

      const { spoiler, ...rest } = data.containerData || {};
      const containerData = {
        ...rest,
        ...(spoiler?.enabled ? { spoiler: { ...spoiler } } : {}),
      };

      const galleryData = data as GalleryData;

      const items = (galleryData.items as PmGalleryNode['attrs']['items'])
        .map(({ loading, error, ...item }) => {
          if (loading || error) {
            return undefined;
          }
          if ('image' in item && item.image) {
            return {
              ...item,
              image: {
                ...item.image,
                link: fromTiptapLinkConverter(item.image.link as any) as Link,
              },
            };
          }

          return item;
        })
        .filter(Boolean);

      if (items.length === 0) {
        return undefined;
      }

      return {
        type: Node_Type.GALLERY,
        id,
        nodes: [],
        galleryData: {
          ...galleryData,
          items: items as GalleryData['items'],
          disableExpand: data.disableExpand || undefined,
          disableDownload: data.disableDownload || undefined,
          containerData: Object.keys(containerData).length ? containerData : undefined,
          ...(animation ? { animation } : {}),
        },
      };
    },
  },
});
