import classNames from 'classnames';
import React, { useEffect, useRef, useState } from 'react';

import classes from '../statics/styles/gallery-media-scss.js';
import type { GalleryMediaPresentation, GalleryMediaRuntime } from './gallery-media-types.js';
import type {
  NormalizedGalleryItem,
  NormalizedGalleryMediaSource,
} from './normalize-gallery-items.js';

const DEFAULT_TARGET_WIDTHS = [320, 640, 960, 1280, 1920];
const THUMBNAIL_TARGET_WIDTHS = [90, 120, 180, 240];
const THUMBNAIL_SIZES = '(max-width: 500px) 90px, 120px';

type GalleryMediaProps = {
  item: NormalizedGalleryItem;
  presentation: GalleryMediaPresentation;
  sizes: string;
  eager: boolean;
  runtime: GalleryMediaRuntime;
  targetWidths?: number[];
};

export const GalleryMedia = ({
  item,
  presentation,
  sizes,
  eager,
  runtime,
  targetWidths = DEFAULT_TARGET_WIDTHS,
}: GalleryMediaProps) => {
  const [failed, setFailed] = useState(false);
  const [videoStarted, setVideoStarted] = useState(false);

  useEffect(() => {
    setFailed(false);
    setVideoStarted(false);
  }, [item.id, item.source.url]);

  const style = { aspectRatio: `${item.width} / ${item.height}` };
  const interactionDeterrents = item.disableDownload
    ? {
        onContextMenu: (event: React.MouseEvent) => event.preventDefault(),
      }
    : {};

  if (failed) {
    return (
      <span
        className={classNames(classes.media, classes.failure)}
        style={style}
        data-hook="gallery-media-failure"
        aria-hidden="true"
      />
    );
  }

  if (item.type === 'video') {
    if (videoStarted) {
      return (
        <span
          className={classNames(classes.media, classes[presentation])}
          style={style}
          data-hook="gallery-media-video"
          {...interactionDeterrents}
        >
          <video
            src={item.source.url}
            controls
            controlsList={item.disableDownload ? 'nodownload' : undefined}
            playsInline
            autoPlay
            loop={false}
            muted={false}
            preload={eager ? 'metadata' : 'none'}
            onError={() => setFailed(true)}
          />
        </span>
      );
    }

    return (
      <span
        className={classNames(classes.media, classes[presentation])}
        style={style}
        data-hook="gallery-media-video-poster"
        {...interactionDeterrents}
      >
        {item.poster ? (
          <GalleryImage
            itemId={item.id}
            source={item.poster}
            alt=""
            presentation={presentation}
            sizes={sizes}
            eager={eager}
            disableDownload={item.disableDownload}
            runtime={runtime}
            targetWidths={targetWidths}
            onError={() => setFailed(true)}
          />
        ) : null}
        <button
          type="button"
          className={classes.playButton}
          aria-label={
            item.title ? `${runtime.playVideoLabel}: ${item.title}` : runtime.playVideoLabel
          }
          onClick={() => setVideoStarted(true)}
          data-hook="gallery-video-play"
        >
          <span className={classes.playIcon} aria-hidden="true" />
        </button>
      </span>
    );
  }

  return (
    <span
      className={classNames(classes.media, classes[presentation])}
      style={style}
      data-hook="gallery-media-image"
      {...interactionDeterrents}
    >
      <GalleryImage
        itemId={item.id}
        source={item.source}
        alt={item.alt}
        presentation={presentation}
        sizes={sizes}
        eager={eager}
        disableDownload={item.disableDownload}
        runtime={runtime}
        targetWidths={targetWidths}
        onError={() => setFailed(true)}
      />
    </span>
  );
};

export const GalleryThumbnailMedia = ({
  item,
  runtime,
}: {
  item: NormalizedGalleryItem;
  runtime: GalleryMediaRuntime;
}) => {
  const source = item.type === 'image' ? item.source : item.poster;
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    setFailed(false);
  }, [item.id, source?.url]);

  if (!source || failed) {
    return (
      <span
        className={classNames(classes.media, classes.failure)}
        data-hook="gallery-thumbnail-media-failure"
        aria-hidden="true"
      />
    );
  }

  return (
    <span
      className={classNames(classes.media, classes.fill)}
      data-hook="gallery-thumbnail-media"
      aria-hidden="true"
    >
      <GalleryImage
        itemId={item.id}
        source={source}
        alt=""
        presentation="fill"
        sizes={THUMBNAIL_SIZES}
        eager
        disableDownload={item.disableDownload}
        runtime={runtime}
        targetWidths={THUMBNAIL_TARGET_WIDTHS}
        targetRatio={1}
        onError={() => setFailed(true)}
      />
    </span>
  );
};

const GalleryImage = ({
  itemId,
  source,
  alt,
  presentation,
  sizes,
  eager,
  disableDownload,
  runtime,
  targetWidths,
  targetRatio,
  onError,
}: {
  itemId: string;
  source: NormalizedGalleryMediaSource;
  alt: string;
  presentation: GalleryMediaPresentation;
  sizes: string;
  eager: boolean;
  disableDownload: boolean;
  runtime: GalleryMediaRuntime;
  targetWidths: number[];
  targetRatio?: number;
  onError: () => void;
}) => {
  const responsiveSource = runtime.createMediaUrl({
    source,
    transformMode: presentation === 'fill' ? 'fill' : 'fit',
    targetWidths,
    targetRatio,
  });
  const imageProps = runtime.imageProps?.(itemId);
  const imageRef = useRef<HTMLImageElement>(null);

  useEffect(() => {
    const image = imageRef.current;
    if (image?.complete && image.naturalWidth === 0) {
      onError();
    }
  }, [onError, responsiveSource.src]);

  return (
    <img
      ref={imageRef}
      {...imageProps}
      src={responsiveSource.src}
      srcSet={responsiveSource.srcSet}
      sizes={responsiveSource.srcSet ? sizes : undefined}
      alt={alt}
      width={source.width}
      height={source.height}
      loading={eager ? 'eager' : 'lazy'}
      draggable={disableDownload ? false : undefined}
      onError={onError}
    />
  );
};
